//! Port of `unidecode` 1.3.8 (`unidecode/__init__.py`: `unidecode_expect_ascii`, `_get_repl_str`,
//! `_unidecode` with `errors='ignore'`), the package `lcd_printer.py:14,530` and `util.py:142` call
//! as `unidecode.unidecode(text)`. GPL-2.0-or-later, Tomaz Solc; the tables are
//! `unidecode_data.rs`, generated by `scripts/prusalink-unidecode-tables.py`.
//!
//! Python's `str` can hold lone surrogates (a `RuntimeWarning` and then the table's entry); a Rust
//! `str` cannot, so that branch does not exist here.

use super::unidecode_data::SECTIONS;

/// The version of the package the tables are from
pub const UNIDECODE_VERSION: &str = super::unidecode_data::UNIDECODE_VERSION;

/// `_get_repl_str(char)`: `None` is Python's `None`
fn get_repl_str(ch: char) -> Option<std::borrow::Cow<'static, str>> {
    let codepoint = ch as u32;
    if codepoint < 0x80 {
        // Already ASCII
        return Some(ch.to_string().into());
    }
    if codepoint > 0xeffff {
        // No data on characters in Private Use Area and above.
        return None;
    }
    let section = (codepoint >> 8) as u16;
    let position = (codepoint % 256) as usize;
    let table = SECTIONS
        .binary_search_by_key(&section, |(s, _)| *s)
        .ok()
        .map(|i| SECTIONS[i].1)?;
    if table.len() > position {
        table[position].map(Into::into)
    } else {
        None
    }
}

/// `unidecode.unidecode(string)`
pub fn unidecode(string: &str) -> String {
    if string.is_ascii() {
        return string.to_string();
    }
    let mut retval = String::new();
    for ch in string.chars() {
        // errors == 'ignore': `repl = ''`
        match get_repl_str(ch) {
            Some(repl) => retval.push_str(&repl),
            None => {}
        }
    }
    retval
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ports::prusalink::python;
    use md5::{Digest, Md5};
    use serde_json::json;

    /// `unidecode.unidecode` and ours on every code point (except the surrogates, which a Rust
    /// `str` cannot hold) and on strings: identical
    #[test]
    fn identical_to_the_package() {
        let strings = [
            "",
            "plain.gcode",
            "Ünïcödé; naïve café.gcode",
            "北亰 Κνωσός Привет",
            "emoji \u{1F600} and \u{e000} and \u{f0000}",
            "a\u{0080}b\u{00a0}c\u{2028}d",
        ];
        let Some(python) = python::run(include_str!("driver_unidecode.py"), &json!(strings)) else {
            return;
        };
        let mut md5 = Md5::new();
        for cp in 0..0x110000u32 {
            let Some(ch) = char::from_u32(cp) else {
                continue;
            };
            md5.update(unidecode(&ch.to_string()).as_bytes());
            md5.update([0u8]);
        }
        let hex: String = md5.finalize().iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(python["md5"], hex);
        let ours: Vec<String> = strings.iter().map(|s| unidecode(s)).collect();
        assert_eq!(python["strings"], json!(ours));
        assert_eq!(UNIDECODE_VERSION, "1.3.8");
    }
}
